-- Ampliar perfiles preservando todas las filas existentes.
CREATE TABLE perfiles_v5 (email TEXT NOT NULL, modulo TEXT NOT NULL CHECK (modulo IN ('prensas','barriles','lotes','vendimia')), rol TEXT NOT NULL CHECK (rol IN ('admin','editor','lector')), nombre TEXT, creado TEXT NOT NULL DEFAULT (datetime('now')), PRIMARY KEY(email,modulo));
INSERT INTO perfiles_v5 SELECT * FROM perfiles;
DROP TABLE perfiles;
ALTER TABLE perfiles_v5 RENAME TO perfiles;
INSERT OR IGNORE INTO perfiles(email,modulo,rol,nombre) SELECT email,'vendimia','admin',nombre FROM usuarios WHERE es_admin=1;
CREATE TABLE vend_lotes (id TEXT PRIMARY KEY, codigo TEXT NOT NULL, anio INTEGER NOT NULL, nombre TEXT NOT NULL, variedad TEXT NOT NULL, estado TEXT NOT NULL DEFAULT 'Recepción', autor TEXT NOT NULL, fecha TEXT NOT NULL, UNIQUE(anio,codigo));
CREATE TABLE vend_recepciones (id TEXT PRIMARY KEY, lote_id TEXT NOT NULL REFERENCES vend_lotes(id), fecha TEXT NOT NULL, autor TEXT NOT NULL, observaciones TEXT NOT NULL DEFAULT '', proveedor TEXT, vinedo TEXT, parcela TEXT, cuartel TEXT, cosecha TEXT, transporte TEXT, recipiente TEXT, bins REAL, ot TEXT);
CREATE INDEX vend_recepciones_lote ON vend_recepciones(lote_id,fecha);
CREATE TABLE vend_pesajes (id TEXT PRIMARY KEY, lote_id TEXT NOT NULL REFERENCES vend_lotes(id), fecha TEXT NOT NULL, autor TEXT NOT NULL, observaciones TEXT NOT NULL DEFAULT '', recepcion_id TEXT NOT NULL REFERENCES vend_recepciones(id), bruto REAL NOT NULL, tara REAL NOT NULL, comprobante TEXT);
CREATE INDEX vend_pesajes_lote ON vend_pesajes(lote_id,fecha);
CREATE TABLE vend_moliendas (id TEXT PRIMARY KEY, lote_id TEXT NOT NULL REFERENCES vend_lotes(id), fecha TEXT NOT NULL, autor TEXT NOT NULL, observaciones TEXT NOT NULL DEFAULT '', ot TEXT NOT NULL, turno TEXT, tipo TEXT, manejo TEXT, prensado TEXT, hielo TEXT, bins REAL, racimos REAL, descobajado REAL, estrujado TEXT, so2 TEXT, merma TEXT, emitio TEXT, recibio TEXT);
CREATE INDEX vend_moliendas_lote ON vend_moliendas(lote_id,fecha);
CREATE TABLE vend_distribuciones (id TEXT PRIMARY KEY, lote_id TEXT NOT NULL REFERENCES vend_lotes(id), fecha TEXT NOT NULL, autor TEXT NOT NULL, observaciones TEXT NOT NULL DEFAULT '', molienda_id TEXT NOT NULL REFERENCES vend_moliendas(id), vasija TEXT NOT NULL, parcela TEXT, cantidad REAL NOT NULL, unidad TEXT NOT NULL, bins REAL, racimos TEXT, descobajado TEXT, estrujado TEXT, so2 TEXT, merma TEXT);
CREATE INDEX vend_distribuciones_lote ON vend_distribuciones(lote_id,fecha);
CREATE TABLE vend_analisis (id TEXT PRIMARY KEY, lote_id TEXT NOT NULL REFERENCES vend_lotes(id), fecha TEXT NOT NULL, autor TEXT NOT NULL, observaciones TEXT NOT NULL DEFAULT '', vasija TEXT, parametro TEXT NOT NULL, resultado REAL NOT NULL, unidad TEXT, etapa TEXT);
CREATE INDEX vend_analisis_lote ON vend_analisis(lote_id,fecha);
CREATE TABLE vend_agregados (id TEXT PRIMARY KEY, lote_id TEXT NOT NULL REFERENCES vend_lotes(id), fecha TEXT NOT NULL, autor TEXT NOT NULL, observaciones TEXT NOT NULL DEFAULT '', ot TEXT, vasija TEXT, producto TEXT NOT NULL, cantidad REAL NOT NULL, unidad TEXT NOT NULL, dosis TEXT, lote_insumo TEXT, estado TEXT, emitio TEXT, recibio TEXT);
CREATE INDEX vend_agregados_lote ON vend_agregados(lote_id,fecha);
CREATE TABLE vend_tintos (id TEXT PRIMARY KEY, lote_id TEXT NOT NULL REFERENCES vend_lotes(id), fecha TEXT NOT NULL, autor TEXT NOT NULL, observaciones TEXT NOT NULL DEFAULT '', vasija TEXT NOT NULL, recepcion TEXT, bins REAL, kg REAL, tipo_vasija TEXT, manejo TEXT, sangria REAL, litros_retirados REAL, vv TEXT, so2 TEXT, mbk TEXT, solucion TEXT, levadura TEXT, dosis TEXT, cantidad TEXT, ot TEXT, descube TEXT, destino TEXT, lote_destino TEXT, estado TEXT);
CREATE INDEX vend_tintos_lote ON vend_tintos(lote_id,fecha);
CREATE TABLE vend_blancos (id TEXT PRIMARY KEY, lote_id TEXT NOT NULL REFERENCES vend_lotes(id), fecha TEXT NOT NULL, autor TEXT NOT NULL, observaciones TEXT NOT NULL DEFAULT '', vasija TEXT NOT NULL, recepcion TEXT, bins REAL, kg REAL, tipo_vasija TEXT, manejo TEXT, prensado TEXT, desborre TEXT, litros_desborre REAL, inicio_desborre TEXT, fin_desborre TEXT, ntu REAL, ntu_final REAL, mbk TEXT, solucion TEXT, fin_fermentacion TEXT, lote_destino TEXT, destino TEXT, lugar TEXT, temperatura REAL, so2 TEXT, levadura TEXT, dosis TEXT, cantidad TEXT, ot TEXT, estado TEXT);
CREATE INDEX vend_blancos_lote ON vend_blancos(lote_id,fecha);
CREATE TABLE vend_mediciones (id TEXT PRIMARY KEY, lote_id TEXT NOT NULL REFERENCES vend_lotes(id), fecha TEXT NOT NULL, autor TEXT NOT NULL, observaciones TEXT NOT NULL DEFAULT '', vasija TEXT NOT NULL, brix REAL NOT NULL, temperatura REAL NOT NULL, muestra TEXT, azucar REAL, ph REAL, az_red REAL, av REAL, mov06 TEXT, mov14 TEXT, mov18 TEXT, mov22 TEXT);
CREATE INDEX vend_mediciones_lote ON vend_mediciones(lote_id,fecha);
CREATE TABLE vend_movimientos (id TEXT PRIMARY KEY, lote_id TEXT NOT NULL REFERENCES vend_lotes(id), fecha TEXT NOT NULL, autor TEXT NOT NULL, observaciones TEXT NOT NULL DEFAULT '', origen TEXT NOT NULL, destino TEXT NOT NULL, tipo TEXT NOT NULL, cantidad REAL NOT NULL, unidad TEXT NOT NULL, ot TEXT);
CREATE INDEX vend_movimientos_lote ON vend_movimientos(lote_id,fecha);
CREATE TABLE vend_checklist (id TEXT PRIMARY KEY, lote_id TEXT NOT NULL REFERENCES vend_lotes(id), fecha TEXT NOT NULL, autor TEXT NOT NULL, observaciones TEXT NOT NULL DEFAULT '', actividad TEXT NOT NULL, horario TEXT, frecuencia TEXT, estado TEXT NOT NULL, responsable_asignado TEXT);
CREATE INDEX vend_checklist_lote ON vend_checklist(lote_id,fecha);
CREATE TABLE vend_degustaciones (id TEXT PRIMARY KEY, lote_id TEXT NOT NULL REFERENCES vend_lotes(id), fecha TEXT NOT NULL, autor TEXT NOT NULL, observaciones TEXT NOT NULL DEFAULT '', vasija TEXT, brix REAL, temperatura REAL, evaluacion TEXT, criterio TEXT);
CREATE INDEX vend_degustaciones_lote ON vend_degustaciones(lote_id,fecha);
CREATE TABLE vend_lavados (id TEXT PRIMARY KEY, lote_id TEXT NOT NULL REFERENCES vend_lotes(id), fecha TEXT NOT NULL, autor TEXT NOT NULL, observaciones TEXT NOT NULL DEFAULT '', ot TEXT, equipo TEXT NOT NULL, producto TEXT, ejecuto TEXT, controlo TEXT, estado TEXT NOT NULL);
CREATE INDEX vend_lavados_lote ON vend_lavados(lote_id,fecha);
CREATE TRIGGER vend_pesaje_validar BEFORE INSERT ON vend_pesajes BEGIN
 SELECT CASE WHEN NEW.bruto < NEW.tara OR NEW.tara < 0 OR NOT EXISTS(SELECT 1 FROM vend_recepciones WHERE id=NEW.recepcion_id AND lote_id=NEW.lote_id) THEN RAISE(ABORT,'pesaje invalido') END;
END;
CREATE TRIGGER vend_distribucion_validar BEFORE INSERT ON vend_distribuciones BEGIN
 SELECT CASE WHEN NEW.cantidad <= 0 OR NEW.unidad NOT IN ('kg','L') OR NOT EXISTS(SELECT 1 FROM vend_moliendas WHERE id=NEW.molienda_id AND lote_id=NEW.lote_id) THEN RAISE(ABORT,'distribucion invalida') END;
END;
CREATE VIEW vend_existencias AS SELECT lote_id, vasija, unidad, SUM(cantidad) cantidad FROM (
 SELECT lote_id,vasija,unidad,cantidad FROM vend_distribuciones UNION ALL
 SELECT lote_id,origen,unidad,-cantidad FROM vend_movimientos UNION ALL
 SELECT lote_id,destino,unidad,cantidad FROM vend_movimientos
) GROUP BY lote_id,vasija,unidad HAVING SUM(cantidad)>0;
CREATE TRIGGER vend_movimiento_validar BEFORE INSERT ON vend_movimientos BEGIN
 SELECT CASE WHEN NEW.cantidad<=0 OR NEW.origen=NEW.destino OR NEW.unidad NOT IN ('kg','L') OR NEW.cantidad>COALESCE((SELECT cantidad FROM vend_existencias WHERE lote_id=NEW.lote_id AND vasija=NEW.origen AND unidad=NEW.unidad),0) THEN RAISE(ABORT,'movimiento sin saldo suficiente') END;
END;
CREATE TRIGGER vend_audit_lotes AFTER INSERT ON vend_lotes BEGIN INSERT INTO auditoria(modulo,tabla,operacion,fila_id,despues,email) VALUES('vendimia','lotes','INSERT',NEW.id, json_object('lote_id',NEW.id,'fecha',NEW.fecha),NEW.autor); END;
